'use strict';

/**
 * Acceptance test for PR #9075: Chat Completions requests must skip
 * Codex custom-tool translation.
 *
 * Before the fix, translateCodexCustomToolsForCopilot was called on every
 * writable Copilot request including /chat/completions routes. When it saw
 * a Chat Completions custom tool ({ type: 'custom', custom: { name } }),
 * it read the name as missing and threw:
 *   "Unsupported Responses custom tool '(unknown)'..."
 *
 * After the fix, isChatCompletionsRequest() guards the translation so that
 * Chat Completions requests pass through unchanged.
 */

const { createBodyHandler } = require('./body-handler');

// Mock dependencies
const mockHandleError = () => {};
const mockOtel = {
  endSpan: () => {},
  endSpanError: () => {},
};

function makeMockRequest(url, method = 'POST') {
  return {
    method,
    url,
    awfRequestContext: null,
    awfRouting: null,
  };
}

function makeBody(customTools) {
  const bodyObj = { model: 'gpt-4', messages: [{ role: 'user', content: 'hello' }] };
  if (customTools && customTools.length > 0) {
    bodyObj.tools = customTools;
  }
  return Buffer.from(JSON.stringify(bodyObj));
}

async function runTest() {
  const handler = createBodyHandler({ handleRequestError: mockHandleError, otel: mockOtel });

  // Test case: Chat Completions URL with a custom tool that would fail translation
  const chatCompletionsUrl = '/chat/completions';
  const customToolBody = makeBody([
    { type: 'custom', custom: { name: 'my_custom_tool' } }
  ]);

  let result;
  try {
    result = await handler.transformRequestBody(
      customToolBody,
      'copilot',
      makeMockRequest(chatCompletionsUrl),
      'test-request-id',
      null
    );
  } catch (err) {
    console.error('FAIL: transformRequestBody threw an error for Chat Completions URL');
    console.error(err.message);
    process.exit(1);
  }

  // Verify the body was NOT translated (should be unchanged)
  const parsedResult = JSON.parse(result.body.toString('utf8'));

  // The tools should still be in their original custom format, not translated
  if (!parsedResult.tools || !parsedResult.tools[0] || parsedResult.tools[0].type !== 'custom') {
    console.error('FAIL: Body was incorrectly transformed for Chat Completions URL');
    console.error('Expected tools to remain as custom type, got:', JSON.stringify(parsedResult.tools));
    process.exit(1);
  }

  // codexCompatibility should be null (no translation happened)
  if (result.codexCompatibility !== null) {
    console.error('FAIL: codexCompatibility should be null for Chat Completions URL');
    console.error('Got:', result.codexCompatibility);
    process.exit(1);
  }

  // Also test /v1/chat/completions variant
  const v1ChatCompletionsUrl = '/v1/chat/completions';
  let result2;
  try {
    result2 = await handler.transformRequestBody(
      customToolBody,
      'copilot',
      makeMockRequest(v1ChatCompletionsUrl),
      'test-request-id-2',
      null
    );
  } catch (err) {
    console.error('FAIL: transformRequestBody threw an error for /v1/chat/completions URL');
    console.error(err.message);
    process.exit(1);
  }

  const parsedResult2 = JSON.parse(result2.body.toString('utf8'));
  if (!parsedResult2.tools || !parsedResult2.tools[0] || parsedResult2.tools[0].type !== 'custom') {
    console.error('FAIL: Body was incorrectly transformed for /v1/chat/completions URL');
    process.exit(1);
  }

  if (result2.codexCompatibility !== null) {
    console.error('FAIL: codexCompatibility should be null for /v1/chat/completions URL');
    process.exit(1);
  }

  // Test with query string and trailing slash
  const chatCompletionsWithQuery = '/chat/completions/?x=1';
  let result3;
  try {
    result3 = await handler.transformRequestBody(
      customToolBody,
      'copilot',
      makeMockRequest(chatCompletionsWithQuery),
      'test-request-id-3',
      null
    );
  } catch (err) {
    console.error('FAIL: transformRequestBody threw an error for /chat/completions/?x=1 URL');
    console.error(err.message);
    process.exit(1);
  }

  const parsedResult3 = JSON.parse(result3.body.toString('utf8'));
  if (!parsedResult3.tools || !parsedResult3.tools[0] || parsedResult3.tools[0].type !== 'custom') {
    console.error('FAIL: Body was incorrectly transformed for /chat/completions/?x=1 URL');
    process.exit(1);
  }

  if (result3.codexCompatibility !== null) {
    console.error('FAIL: codexCompatibility should be null for /chat/completions/?x=1 URL');
    process.exit(1);
  }

  // Verify that non-Chat-Completions routes still get translation applied
  // (apply_patch should be translated to function tool)
  const responsesUrl = '/responses';
  const applyPatchBody = makeBody([
    { type: 'custom', name: 'apply_patch' }
  ]);

  let result4;
  try {
    result4 = await handler.transformRequestBody(
      applyPatchBody,
      'copilot',
      makeMockRequest(responsesUrl),
      'test-request-id-4',
      null
    );
  } catch (err) {
    console.error('FAIL: transformRequestBody threw an error for /responses URL with apply_patch');
    console.error(err.message);
    process.exit(1);
  }

  const parsedResult4 = JSON.parse(result4.body.toString('utf8'));

  // For /responses, apply_patch should be translated to function type
  if (!parsedResult4.tools || !parsedResult4.tools[0] || parsedResult4.tools[0].type !== 'function') {
    console.error('FAIL: apply_patch on /responses should be translated to function tool');
    console.error('Got:', JSON.stringify(parsedResult4.tools));
    process.exit(1);
  }

  // codexCompatibility should NOT be null for /responses with apply_patch
  if (result4.codexCompatibility === null) {
    console.error('FAIL: codexCompatibility should NOT be null for /responses with apply_patch');
    process.exit(1);
  }

  console.log('PASS: All Chat Completions requests correctly skip Codex custom-tool translation');
  console.log('PASS: Non-Chat-Completions routes still get proper translation');
}

runTest().catch(err => {
  console.error('Unexpected error:', err);
  process.exit(1);
});
